'use strict';

const fs = require('node:fs');
const path = require('node:path');
const H = require('./shell-page.cjs');
const ROOT = H.ROOT;
let css;

async function styles() {
    if (process.env.PDF_PRINT_CSS) return fs.readFileSync(process.env.PDF_PRINT_CSS, 'utf8');
    if (css) return css;
    const filename = path.join(ROOT, 'apps/pdfeditor/main/resources/less/app.less');
    // Icon sprites are generated by Grunt; their backgrounds do not affect this fixture's layout.
    const source = fs.readFileSync(filename, 'utf8').replace(/^@import\s+"(sprites\/[^"\n]+)";.*$/gm,
        (line, name) => fs.existsSync(path.join(path.dirname(filename), name + '.less')) ? line : '');
    css = (await require('less').render(source, {filename})).css;
    return css;
}

const modules = [
    'apps/common/main/lib/core/NotificationCenter.js',
    'apps/common/main/lib/component/BaseView.js',
    'apps/common/main/lib/core/application.js',
    'apps/common/main/lib/util/utils.js',
    'apps/common/Gateway.js',
    'apps/common/main/lib/util/LocalStorage.js',
    'apps/common/main/lib/controller/Scaling.js',
    'apps/common/main/lib/mods/dropdown.js',
    'apps/common/main/lib/mods/tooltip.js',
    'apps/common/main/lib/extend/Bootstrap.js',
    'vendor/perfect-scrollbar/src/jquery.mousewheel.js',
    'vendor/perfect-scrollbar/src/perfect-scrollbar.js',
    'apps/common/main/lib/component/Scroller.js',
    'apps/common/main/lib/component/ToggleManager.js',
    'apps/common/main/lib/component/Button.js',
    'apps/common/main/lib/component/Tooltip.js',
    'apps/common/main/lib/component/CheckBox.js',
    'apps/common/main/lib/component/MenuItem.js',
    'apps/common/main/lib/component/Menu.js',
    'apps/common/main/lib/component/ComboBox.js',
    'apps/common/main/lib/component/InputField.js',
    'apps/common/main/lib/component/MetricSpinner.js',
    'apps/common/main/lib/controller/FocusManager.js',
    'apps/common/main/lib/component/Window.js',
    'apps/common/main/lib/view/compact/Windows.js',
    'apps/common/main/lib/view/compact/DocInfoWindow.js',
    'apps/pdfeditor/main/app/view/FileMenuPanels.js',
    'apps/pdfeditor/main/app/controller/Print.js',
    'apps/pdfeditor/main/app/view/FileWindows.js',
    'apps/pdfeditor/main/app/view/CompactWindows.js'
];

function sdkBoundary(locale) {
    window.isrtl = false;
    window.Common = {UI: {}, Utils: {}, Locale: {getCurrentLanguage: () => locale, isCurrentLanguageRtl: () => false}};
    window.PDFE = {Views: {}, Controllers: {}};
    window.Asc = {
        c_oAscFileType: {DOCX: 65, PDF: 513},
        c_oAscPageOrientation: {PagePortrait: 0, PageLandscape: 1},
        asc_CAdjustPrint: function () {},
        asc_CDownloadOptions: function (type) { this.type = type; }
    };
    Asc.asc_CAdjustPrint.prototype.asc_setPdfContent = function (value) { this.content = value; };
    Asc.asc_CAdjustPrint.prototype.asc_getPdfContent = function () { return this.content; };
    Asc.asc_CAdjustPrint.prototype.asc_setNativeOptions = function (value) { this.native = value; };
    Asc.asc_CDownloadOptions.prototype.asc_setAdvancedOptions = function (value) { this.advanced = value; };
    window.AscPDF = {PRINT_CONTENT_TYPES: {doc: 0, docAndMarkups: 1, docAndStamps: 2, formsOnly: 3}};
    window.define = function (deps, factory) {
        return factory.apply(null, deps.map(name => name === 'backbone' ? Backbone : name === 'underscore' ? _ : undefined));
    };
}

function install({compact, canPrint}) {
    const bus = new Backbone.EventBus();
    const fileMenu = _.extend({hide() { this.trigger('menu:hide'); }}, Backbone.Events);
    const calls = [];
    const api = {
        asc_getPageSize() { return {W: 210, H: 297}; },
        asc_drawPrintPreview() {},
        asc_closePrintPreview() {},
        asc_Print(options) { calls.push({action: 'print', content: options.advanced.content}); },
        asc_DownloadAs(options) { calls.push({action: 'pdf', content: options.advanced.content}); }
    };
    const app = {
        addListeners(listeners, controller) { bus.addListeners(listeners, controller); },
        getController(name) { return name === 'Print' ? controller : {onTryPrint(callback) { callback(); }}; }
    };
    bus.application = app;
    const controller = new PDFE.Controllers.Print({application: app, id: 'Print'});
    // The viewer/SDK boundary is external; all controls and their resize logic remain real.
    controller.api = api;
    const panel = new PDFE.Views.PrintWithPreview({menu: fileMenu, alias: 'PrintWithPreview'});
    controller.printSettings = panel;
    controller._viewsCache = {PrintWithPreview: panel};
    panel.setMode({isDesktopApp: false});
    const fileScreen = document.getElementById('file-menu-panel');
    panel.render(fileScreen.querySelector('#panel-print'));
    controller.onAfterRender(panel);
    panel.on('show', () => controller.adjPrintParams.asc_setPdfContent(panel.cmbContent.getValue()));
    PDFE.getController = name => name === 'Print' ? controller : app.getController(name);
    PDFE.Views.PdfActions = {canPrint: () => canPrint};
    PDFE.Views.StockBridge = {filePanel: name => name === 'printpreview' ? panel : null};
    PDFE.Views.CompactWindows.install({advanced: !compact, guarded: (name, fn) => fn});
    window.printFixture = {panel, controller, calls, fileMenu,
        open() { return PDFE.Views.FileWindows.open('printpreview'); },
        close() { const w = PDFE.Views.FileWindows.opened.printpreview; if (w) w.close(); },
        resize() { Common.NotificationCenter.trigger('window:resize'); }
    };
    if (compact) {
        fileScreen.style.display = 'none';
        printFixture.open();
    }
}

async function open(browser, options = {}) {
    const page = await browser.newPage({viewport: {width: options.width || 1280, height: options.height || 800}});
    page.setDefaultTimeout(5000);
    page.errors = [];
    page.on('pageerror', error => page.errors.push(error.stack || error.message));
    await page.route('http://print.test/**', route => {
        const pathname = new URL(route.request().url()).pathname;
        const file = path.resolve(ROOT, '.' + pathname.replace(/^\/web-apps/, ''));
        if (!pathname.endsWith('/index.html') && file.startsWith(ROOT + path.sep) && fs.existsSync(file) && fs.statSync(file).isFile()) {
            return route.fulfill({body: fs.readFileSync(file), contentType: file.endsWith('.svg') ? 'image/svg+xml' : 'application/octet-stream'});
        }
        return route.fulfill({contentType: 'text/html', body: '<!doctype html><html><head></head><body>' +
            '<div id="editor_sdk" style="position:fixed;inset:0"></div>' +
            '<div id="file-menu-panel"><div id="panel-print" class="content-box"></div></div></body></html>'});
    });
    await page.goto('http://print.test/web-apps/apps/pdfeditor/main/index.html');
    await page.addStyleTag({content: await styles()});
    for (const name of ['jquery', 'underscore', 'backbone']) {
        await page.addScriptTag({path: path.join(ROOT, 'vendor', name, name + '.js')});
    }
    await page.evaluate(sdkBoundary, options.locale || 'en');
    await page.evaluate(({compact, theme}) => {
        document.body.className = theme + (theme === 'theme-dark' ? ' theme-type-dark' : '') + (compact ? ' vo-compact' : '');
    }, {compact: options.compact !== false, theme: options.theme || 'theme-white'});
    for (const file of modules) await page.addScriptTag({path: path.join(ROOT, file)});
    if (options.locale && options.locale !== 'en') {
        await page.evaluate(messages => {
            for (const [key, value] of Object.entries(messages)) {
                const parts = key.split('.');
                let target = window;
                for (let i = 0; i < parts.length - 1 && target; i++) target = target[parts[i]];
                if (target && (typeof target === 'function' || typeof target === 'object')) {
                    (target.prototype || target)[parts[parts.length - 1]] = value;
                }
            }
        }, JSON.parse(fs.readFileSync(path.join(ROOT, 'apps/pdfeditor/main/locale', options.locale + '.json'), 'utf8')));
    }
    await page.evaluate(install, {compact: options.compact !== false, canPrint: options.canPrint !== false});
    await H.settle(page);
    if (page.errors.length) throw new Error(page.errors.join('\n'));
    return page;
}

module.exports = {open, styles};
